const clamp=(v,a,b)=>Math.max(a,Math.min(b,v)),TAU=Math.PI*2,wrap=a=>((a+Math.PI)%TAU+TAU)%TAU-Math.PI;
const condition=m=>{const p=partSpec(m);return p?clamp(m.hp/p.hp,0,1):0;};
