 event(text,side,kind=null,data={}){const inferred=kind||(/overheated|back online|heat/i.test(text)?'overheat':/reactor captured/i.test(text)?'capture':/core destroyed/i.test(text)?'core':/battery chain/i.test(text)?'battery':/lost .*?(weapon|cannon|gun|wheel|tread|cooler|reactor|battery)/i.test(text)?'module':/Cover destroyed/i.test(text)?'cover':'status');const event={t:this.time,text,side,kind:inferred,...data};this.events.push(event);this.timeline.push(event);if(this.events.length>140)this.events.shift();}
 active(v){return v.modules.filter(m=>m.hp>0);}
