 recalc(v){const active=this.active(v);v.s=stats({modules:active});const dynamic=(key)=>active.reduce((n,m)=>n+(partSpec(m)[key]||0)*(key==='power'?powerOutputFactor(m):outputFactor(m)),0);const core=active.find(m=>m.id==='core');v.s.power=dynamic('power')*(core?1:.32);v.s.cooling=dynamic('cooling')*(core?1:.35);v.s.thrust=active.filter(m=>!(m.z||0)).reduce((n,m)=>n+(partSpec(m).thrust||0)*outputFactor(m),0);v.s.capacity=(100+dynamic('capacity'))*(core?1:.55);v.s.shield=dynamic('shield');v.s.dps=active.reduce((n,m)=>{const p=partSpec(m);return n+(p.rate?(p.damage*(p.pellets||1)/p.rate)*outputFactor(m):0);},0);v.s.heat=active.reduce((n,m)=>{const p=partSpec(m);return n+(p.rate?(p.heat/p.rate)*outputFactor(m):0);},0);v.s.energy=active.reduce((n,m)=>{const p=partSpec(m);return n+(p.rate?(p.energy/p.rate)*outputFactor(m):0);},0)+active.reduce((n,m)=>n+(partSpec(m).drain||0),0);v.s.speed=v.s.thrust?Math.min(115,(28+55*v.s.thrust/Math.max(1,v.s.mass))*(1+Math.min(2,v.s.boosters)*.1)):0;const f=(v.front||0)*Math.PI/2,right=(m)=>(m.x-v.cx)*Math.cos(f)+(m.y-v.cy)*Math.sin(f);v.s.leftThrust=active.filter(m=>!(m.z||0)&&partSpec(m).thrust&&right(m)<0).reduce((n,m)=>n+partSpec(m).thrust*outputFactor(m),0);v.s.rightThrust=active.filter(m=>!(m.z||0)&&partSpec(m).thrust&&right(m)>=0).reduce((n,m)=>n+partSpec(m).thrust*outputFactor(m),0);const sensors=active.filter(m=>m.id==='sensor');v.s.sensor=clamp((core?outputFactor(core)*.55:0)+sensors.reduce((n,m)=>n+outputFactor(m)*.6,0),0,1);v.s.sensors=sensors.length;v.radius=Math.max(22,...active.map(m=>Math.hypot(m.x-v.cx,m.y-v.cy)*CELL+13));v.maxEnergy=v.s.capacity;v.ground=terrainAt(this.arena,v.x,v.y,this.time).height+(v.s.hovering?6:0);v.combatState=this.combatState(v);v.dead=v.combatState==='destroyed';return v.s;}
