 abilityStatus(side,id){const v=this.vehicles[side],a=ABILITIES[id];if(!a)return 'Unknown command';if(v.dead)return 'Machine destroyed';if(this.result)return 'Battle ended';if(this.time<2)return 'Arming';if(v.disabled>0)return 'EMP disabled';if(id==='smoke'&&!this.active(v).some(m=>m.id==='smoke'))return 'Fit smoke launcher';if(v.abilityCD[id]>0)return v.abilityCD[id].toFixed(1)+'s';if(v.energy<a.cost)return 'Need '+a.cost+' energy';return '';}
 command(side,type,data={}){if(this.replaying||this.mode!=='command'||side!==0||this.result||this.vehicles[side]?.dead)return {ok:false,reason:'Commands unavailable.'};if(!this.validCommand(type,data))return {ok:false,reason:'Invalid command.'};if(type==='ability'){const reason=this.abilityStatus(side,data.id);if(reason)return {ok:false,reason};}if(this.pending.length>30)return {ok:false,reason:'Too many queued commands.'};this.pending.push({tick:this.tick+1,side,type,data:clone(data)});return {ok:true};}
 validCommand(type,d){if(!d||typeof d!=='object')return false;if(type==='ability')return Object.hasOwn(ABILITIES,d.id);if(type==='move')return Number.isFinite(d.x)&&Number.isFinite(d.y)&&d.x>=0&&d.x<=WIDTH&&d.y>=0&&d.y<=HEIGHT;if(type==='drive')return Number.isFinite(d.x)&&Number.isFinite(d.y)&&Math.abs(d.x)<=1&&Math.abs(d.y)<=1;if(type==='order')return ['auto','attack','flank','retreat','hold'].includes(d.id);if(type==='target')return ['weapons','core','power','mobility','nearest'].includes(d.id);if(type==='focus')return Number.isInteger(d.uid)&&d.uid>=1000&&d.uid<1243;if(type==='fire')return typeof d.hold==='boolean';return false;}
 applyCommand(c,record=true){if(!this.validCommand(c.type,c.data))return false;const v=this.vehicles[c.side];if(!v||v.dead)return false;const d=c.data;if(c.type==='ability'&&!this.activate(c.side,d.id))return false;if(c.type==='move'){v.waypoint={x:d.x,y:d.y};v.order='auto';v.drive={x:0,y:0};this.event('Move order received.',v.side);}if(c.type==='drive'){v.drive={x:d.x,y:d.y};v.waypoint=null;}if(c.type==='order'){v.order=d.id;v.waypoint=null;v.drive={x:0,y:0};this.event('Order: '+d.id+'.',v.side);}if(c.type==='target'){v.target=d.id;v.focusUid=null;this.event('Target priority: '+d.id+'.',v.side);}if(c.type==='focus'){v.focusUid=d.uid;this.event('Focus fire on selected module.',v.side);}if(c.type==='fire')v.holdFire=d.hold;if(record)this.commands.push(clone(c));v.commandCount++;return true;}
