 detach(v){if(v.dead)return;const active=this.active(v),con=active.some(m=>m.id==='core')?connected(active):supportGraph(active);let n=0;for(const m of active){if(con.has(keyOf(m)))continue;const pos=world(v,m);this.debris.push({...pos,r:v.a,id:m.id,age:0,spin:(this.fxRandom()-.5)*2,vx:v.vx*.7+(this.fxRandom()-.5)*25,vy:v.vy*.7+(this.fxRandom()-.5)*25,vh:15});m.hp=0;n++;}if(n){v.detached+=n;this.event(v.name+': '+n+' unsupported module'+(n===1?'':'s')+' collapsed!',v.side);}}
 chooseTarget(v,enemy){const active=this.active(enemy);if(v.focusUid!=null){const m=active.find(m=>m.uid===v.focusUid);if(m)return {m,pos:world(enemy,m),score:0};v.focusUid=null;}let candidates=active.filter(m=>v.target==='weapons'?BY_ID[m.id].cat==='Weapons':v.target==='power'?(BY_ID[m.id].cat==='Systems'||m.id==='shield'):v.target==='mobility'?!!BY_ID[m.id].thrust:v.target==='core'?m.id==='core':true);if(!candidates.length)candidates=active;return candidates.reduce((best,m)=>{const pos=world(enemy,m),distance=Math.hypot(pos.x-v.x,pos.y-v.y),score=distance+m.hp*.04;return !best||score<best.score?{m,pos,score}:best;},null);}
